{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "A tocotrienol-rich fraction, the closest analogue combining a polar oxygenated ring with an unsaturated isoprenoid tail, showed poor oral bioavailability in humans, supporting F <20% for the ubiquinone-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In humans, lycopene, a large isoprenoid lipid, had only ~2.6% systemic availability from a capsule dose, demonstrating that high-molecular-weight isoprenoid lipids can fall far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Phytoene, the highest-similarity analogue, was estimated at 58.5% bioavailability in humans, suggesting that some flexible isoprenoid lipids are well absorbed; however, it lacks the polar quinone ring of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Hyperforin, a prenylated cyclic ketone, showed high oral bioavailability in volunteers, providing a counterexample of a lipophilic prenylated natural product with good absorption, but its lower similarity and different ring system limit transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polyprenyl quinone (ubiquinone-like). The closest structural analogue with a polar ring and isoprenoid tail, tocotrienol, has poor oral bioavailability, and lycopene shows very low systemic availability in humans. Although phytoene and hyperforin are high-bioavailability counterexamples, their transferability is limited by the absence of the polar quinone system or lower structural similarity. Overall, affirmative low-bioavailability evidence outweighs the high-bioavailability analogues, so F <20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone-9/CoQ9 in the evidence set.",
    "Tocotrienol 'poor' bioavailability is not quantitatively tied to the 20% threshold.",
    "Carotenoid data (phytoene vs lycopene) are structurally related but may not capture quinone-specific absorption behavior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

